#include "RHDatagram.h"
RHDatagram::RHDatagram(RHGenericDriver& d,uint8_t a):_driver(d),_thisAddress(a){}
bool RHDatagram::init(){_driver.setThisAddress(_thisAddress);_driver.setHeaderFrom(_thisAddress);return _driver.init();}
void RHDatagram::setThisAddress(uint8_t a){_thisAddress=a;_driver.setThisAddress(a);_driver.setHeaderFrom(a);} bool RHDatagram::sendto(uint8_t* b,uint8_t l,uint8_t a){_driver.setHeaderTo(a);_driver.setHeaderFrom(_thisAddress);return _driver.send(b,l);} bool RHDatagram::recvfrom(uint8_t* b,uint8_t* l,uint8_t* f,uint8_t* t,uint8_t* id,uint8_t* fl){if(!_driver.recv(b,l))return false; if(f)*f=_driver.headerFrom(); if(t)*t=_driver.headerTo(); if(id)*id=_driver.headerId(); if(fl)*fl=_driver.headerFlags(); return true;}
bool RHDatagram::available(){return _driver.available();} void RHDatagram::waitAvailable(){_driver.waitAvailable();} bool RHDatagram::waitPacketSent(){return _driver.waitPacketSent();} bool RHDatagram::waitPacketSent(uint16_t t){return _driver.waitPacketSent(t);} bool RHDatagram::waitAvailableTimeout(uint16_t t){return _driver.waitAvailableTimeout(t);} void RHDatagram::setHeaderTo(uint8_t v){_driver.setHeaderTo(v);} void RHDatagram::setHeaderFrom(uint8_t v){_driver.setHeaderFrom(v);} void RHDatagram::setHeaderId(uint8_t v){_driver.setHeaderId(v);} void RHDatagram::setHeaderFlags(uint8_t s,uint8_t c){_driver.setHeaderFlags(s,c);} uint8_t RHDatagram::headerTo(){return _driver.headerTo();} uint8_t RHDatagram::headerFrom(){return _driver.headerFrom();} uint8_t RHDatagram::headerId(){return _driver.headerId();} uint8_t RHDatagram::headerFlags(){return _driver.headerFlags();} uint8_t RHDatagram::thisAddress(){return _thisAddress;}
